                return "goog_$sub"
            }
        }
        "goog_" + UUID.nameUUIDFromBytes(fallbackEmail.toByteArray()).toString()
    } catch (e: Exception) {
        "goog_" + UUID.nameUUIDFromBytes(fallbackEmail.toByteArray()).toString()
    }
}

