    private fun saveEntitlement(uid: String, purchase: Purchase) {
        prefs.edit()
            .putBoolean(KEY_IS_VIP_PREFIX + uid, true)
            .putLong(KEY_VERIFIED_AT_PREFIX + uid, System.currentTimeMillis())
            .putString(KEY_PURCHASE_TOKEN_PREFIX + uid, purchase.purchaseToken)
            .putString(KEY_ORDER_ID_PREFIX + uid, purchase.orderId)
            .apply()
        _isVipActive.value = true
        Log.i(TAG, "VIP entitlement granted successfully for user: $uid")
    }

    fun revokeEntitlement(uid: String? = null) {
        synchronized(this) {
            currentSessionGeneration++
            val editor = prefs.edit()
            if (uid != null) {
                editor.remove(KEY_IS_VIP_PREFIX + uid)
                editor.remove(KEY_PURCHASE_TOKEN_PREFIX + uid)
                editor.remove(KEY_ORDER_ID_PREFIX + uid)
            }
            editor.apply()
            if (uid == null || uid == currentActiveUid) {
                _isVipActive.value = false
            }
        }
        Log.i(TAG, "VIP entitlement revoked locally.")
    }

    fun activateTestVip(uid: String = "test_user", orderId: String = "GPA.TEST-" + System.currentTimeMillis()) {
        if (!BuildConfig.DEBUG) {
            Log.e(TAG, "activateTestVip is strictly forbidden in release builds.")
            return
        }
        val testToken = "test_token_" + java.util.UUID.randomUUID().toString()
        prefs.edit()
            .putBoolean(KEY_IS_VIP_PREFIX + uid, true)
            .putLong(KEY_VERIFIED_AT_PREFIX + uid, System.currentTimeMillis())
            .putString(KEY_PURCHASE_TOKEN_PREFIX + uid, testToken)
            .putString(KEY_ORDER_ID_PREFIX + uid, orderId)
            .apply()
        _isVipActive.value = true
        Log.i(TAG, "VIP entitlement activated for testing ($orderId).")
    }

    fun isTestVip(uid: String): Boolean {
        val orderId = prefs.getString(KEY_ORDER_ID_PREFIX + uid, null)
        val token = prefs.getString(KEY_PURCHASE_TOKEN_PREFIX + uid, null)
        return orderId?.startsWith("GPA.TEST") == true || token?.startsWith("test_token_") == true
    }

    fun getBackendUrl(): String? {
        val saved = prefs.getString(KEY_BACKEND_URL, null)
        if (!saved.isNullOrEmpty()) return saved
        return try {
            val appInfo = context.packageManager.getApplicationInfo(
                context.packageName,
                android.content.pm.PackageManager.GET_META_DATA
            )
            appInfo.metaData?.getString("com.temulator.app.BACKEND_VERIFY_URL")
        } catch (e: Exception) {
            null
        }
    }

    fun setBackendUrl(url: String) {
        prefs.edit().putString(KEY_BACKEND_URL, url).apply()
    }
}

package com.temulator.app

import android.os.Bundle
import android.widget.LinearLayout
import androidx.activity.addCallback
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.fragment.app.Fragment
import com.google.android.material.bottomnavigation.BottomNavigationView

class MainActivity : AppCompatActivity() {

    private lateinit var bottomNav: BottomNavigationView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        val mainRoot = findViewById<LinearLayout>(R.id.mainRoot)
        bottomNav = findViewById(R.id.bottomNav)

        ViewCompat.setOnApplyWindowInsetsListener(mainRoot) { _, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars() or WindowInsetsCompat.Type.displayCutout())
            mainRoot.setPadding(systemBars.left, systemBars.top, systemBars.right, 0)
            insets
        }

        if (savedInstanceState == null) {
            switchFragment(HomeFragment(), "home")
        }

        bottomNav.setOnItemSelectedListener { item ->
            when (item.itemId) {
                R.id.nav_home -> {
                    switchFragment(HomeFragment(), "home")
                    true
                }
                R.id.nav_games -> {
                    switchFragment(GamesFragment(), "games")
                    true
                }
                R.id.nav_more -> {
                    switchFragment(MoreFragment(), "more")
                    true
                }
                else -> false
            }
        }

        // When user presses back button, return to Home tab if on another tab
        onBackPressedDispatcher.addCallback(this) {
            if (bottomNav.selectedItemId != R.id.nav_home) {
                bottomNav.selectedItemId = R.id.nav_home
            } else {
                isEnabled = false
                onBackPressedDispatcher.onBackPressed()
            }
        }
    }

    private fun switchFragment(fragment: Fragment, tag: String) {
        supportFragmentManager.beginTransaction()
            .replace(R.id.fragmentContainer, fragment, tag)
            .commit()
    }
}

