class AuthRepository private constructor(private val context: Context) {

    private val prefs = context.getSharedPreferences("auth_session", Context.MODE_PRIVATE)
    private val credentialManager = CredentialManager.create(context)
    private val generationCounter = java.util.concurrent.atomic.AtomicLong(1L)

    private val _sessionState = MutableStateFlow<UserSession>(createInitialSession())
    val sessionState: StateFlow<UserSession> = _sessionState.asStateFlow()

    private val _authState = MutableStateFlow<AuthState>(
        _sessionState.value.user?.let { AuthState.Authenticated(it) } ?: AuthState.Unauthenticated
    )
    val authState: StateFlow<AuthState> = _authState.asStateFlow()

    init {
        try {
            val fbAuth = FirebaseAuth.getInstance()
            fbAuth.addAuthStateListener { auth ->
                val fbUser = auth.currentUser
                val current = _sessionState.value
                if (fbUser != null) {
                    val user = UserAccount(
                        uid = fbUser.uid,
                        displayName = fbUser.displayName,
                        email = fbUser.email,
                        photoUrl = fbUser.photoUrl?.toString()
                    )
                    saveSession(user)
                    val newGen = if (current.uid != fbUser.uid) generationCounter.incrementAndGet() else current.generation
                    _authState.value = AuthState.Authenticated(user)
                    _sessionState.value = UserSession(fbUser.uid, newGen, user)
                } else if (!BuildConfig.DEBUG || !isTestAccount()) {
                    clearProfilePrefs()
                    val newGen = if (current.uid != null) generationCounter.incrementAndGet() else current.generation
                    _authState.value = AuthState.Unauthenticated
                    _sessionState.value = UserSession(null, newGen, null)
                }
            }
        } catch (e: Exception) {
            Log.w(TAG, "FirebaseAuth listener not initialized or unavailable", e)
        }
    }

