package com.temulator.app.billing

import com.temulator.app.auth.UserAccount
import com.temulator.app.auth.UserSession
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class VipCachePolicyTest {

    private val now = 1_700_000_000_000L

    @Test
    fun testYearlyValidWithinTtlAndExpiry() {
        val record = VipCacheRecord(
            isVip = true,
            productId = "vip_yearly",
            isLifetime = false,
            expiryTimeMillis = now + 86_400_000L, // expires in 24 hours
            verifiedAt = now - 3_600_000L // verified 1 hour ago
        )
        assertTrue("Yearly within both TTL and expiry must be valid", VipCachePolicy.isValid(record, now))
    }

    @Test
    fun testYearlyExpiredDuringTtlIsDenied() {
        val record = VipCacheRecord(
            isVip = true,
            productId = "vip_yearly",
            isLifetime = false,
            expiryTimeMillis = now - 1_000L, // expired 1 sec ago
            verifiedAt = now - 3_600_000L // verified 1 hour ago (within 24h TTL)
        )
        assertFalse("Yearly expired subscription must be denied even if verifiedAt is within TTL", VipCachePolicy.isValid(record, now))
    }

    @Test
    fun testLifetimeValidWithinTtl() {
        val record = VipCacheRecord(
            isVip = true,
            productId = "vip_lifetime",
            isLifetime = true,
            expiryTimeMillis = null,
            verifiedAt = now - 3_600_000L
        )
        assertTrue("Lifetime within TTL must be valid", VipCachePolicy.isValid(record, now))
    }

    @Test
    fun testLifetimeTtlExpiredIsDenied() {
        val record = VipCacheRecord(
            isVip = true,
            productId = "vip_lifetime",
            isLifetime = true,
            expiryTimeMillis = null,
            verifiedAt = now - (VipCachePolicy.DEFAULT_TTL_MILLIS + 10_000L)
        )
        assertFalse("Lifetime record exceeding TTL must be denied until refreshed", VipCachePolicy.isValid(record, now))
    }

    @Test
    fun testClockRollbackDenied() {
        val record = VipCacheRecord(
            isVip = true,
            productId = "vip_lifetime",
            isLifetime = true,
            expiryTimeMillis = null,
            verifiedAt = now + 60_000L // verifiedAt is in the future
        )
        assertFalse("Clock rollback where verifiedAt > now must be denied", VipCachePolicy.isValid(record, now))
    }

    @Test
    fun testLegacyMissingMetadataDenied() {
        val legacyYearlyMissingExpiry = VipCacheRecord(
            isVip = true,
            productId = "vip_yearly",
            isLifetime = false,
            expiryTimeMillis = null,
            verifiedAt = now - 1_000L
        )
        assertFalse("Legacy yearly with null expiry must be denied", VipCachePolicy.isValid(legacyYearlyMissingExpiry, now))

        val legacyZeroVerifiedAt = VipCacheRecord(
            isVip = true,
            productId = "vip_lifetime",
            isLifetime = true,
            expiryTimeMillis = null,
            verifiedAt = 0L
        )
        assertFalse("Legacy missing verifiedAt must be denied", VipCachePolicy.isValid(legacyZeroVerifiedAt, now))
    }

    @Test
    fun testAuthSessionGenerationMonotonicAcrossLogoutAndLogin() {
        val userA = UserAccount("user_A", "User A", "a@example.com", null)
        val genCounter = java.util.concurrent.atomic.AtomicLong(1L)

        // Initial login A
        val session1 = UserSession("user_A", genCounter.get(), userA)

        // Logout
        val logoutGen = genCounter.incrementAndGet()
        val session2 = UserSession(null, logoutGen, null)

        // Login A again (A -> logout -> A)
        val loginAGen = genCounter.incrementAndGet()
        val session3 = UserSession("user_A", loginAGen, userA)

        assertEquals("user_A", session1.uid)
        assertNotEquals(session1.generation, session2.generation)
        assertNotEquals(session2.generation, session3.generation)
        assertNotEquals(session1.generation, session3.generation)
        assertTrue(session3.generation > session1.generation)
    }

    @Test
    fun testStaleSessionVerificationRejectedWhenSessionChanged() {
        var currentGen = 1L
        var currentUid: String? = "user_A"

        fun capture(): UserSession = UserSession(currentUid, currentGen, null)
        fun isCurrent(session: UserSession): Boolean = session.generation == currentGen && session.uid == currentUid

        // User A starts verification
        val capturedRequestSession = capture()
        assertTrue(isCurrent(capturedRequestSession))

        // Meanwhile, User A logs out and User B logs in
        currentGen++
        currentUid = "user_B"

        // Stale response arrives for user A
        assertFalse("Stale response must be rejected when user switched to B", isCurrent(capturedRequestSession))

        // If User B logs out and User A logs in again
        currentGen++
        currentUid = "user_A"

        assertFalse("Stale response from earlier session 1 must be rejected for session 3 even with same UID", isCurrent(capturedRequestSession))
    }
}

